    public function testProviderOwnsApplicationContainerDependencyDefaults(): void
    {
        $provider = self::dependencyProvider();

        $this->assertInstanceOf(application_adapter_registry::class, $provider->applicationAdapterRegistry());
        $this->assertInstanceOf(application_state_registry::class, $provider->applicationStateRegistry());
        $this->assertInstanceOf(application_model_factory_provider::class, $provider->applicationModelFactoryProvider());
        $this->assertInstanceOf(service_factory_registry::class, $provider->applicationServiceFactoryRegistry());
        $this->assertInstanceOf(application_runtime_factory_provider::class, $provider->applicationRuntimeFactoryProvider());
        $this->assertInstanceOf(application_deferred_service_factory_provider::class, $provider->applicationDeferredServiceFactoryProvider());
        $this->assertInstanceOf(application_support_service_registrar::class, $provider->applicationSupportServiceRegistrar());
        $this->assertInstanceOf(application_core_service_registrar::class, $provider->applicationCoreServiceRegistrar());
        $this->assertInstanceOf(application_infrastructure_service_registrar::class, $provider->applicationInfrastructureServiceRegistrar());
        $this->assertInstanceOf(application_content_service_registrar::class, $provider->applicationContentServiceRegistrar());
        $this->assertInstanceOf(application_navigation_service_registrar::class, $provider->applicationNavigationServiceRegistrar());
        $this->assertInstanceOf(application_controller_service_registrar::class, $provider->applicationControllerServiceRegistrar());
        $this->assertInstanceOf(application_client_service_registrar::class, $provider->applicationClientServiceRegistrar());
        $this->assertInstanceOf(application_pager_service_registrar::class, $provider->applicationPagerServiceRegistrar());
        $this->assertInstanceOf(application_utility_service_registrar::class, $provider->applicationUtilityServiceRegistrar());
        $this->assertFalse(method_exists($provider, 'applicationDatabaseServiceRegistrar'));
        $this->assertFalse(method_exists($provider, 'applicationEmailServiceRegistrar'));
        $this->assertInstanceOf(application_session_service_registrar::class, $provider->applicationSessionServiceRegistrar());
        $this->assertInstanceOf(application_user_service_registrar::class, $provider->applicationUserServiceRegistrar());
        $this->assertInstanceOf(application_service_graph_registrar::class, $provider->applicationServiceGraphRegistrar());
        $this->assertTrue(class_exists(application_service_graph_registration_context::class));
        $this->assertInstanceOf(application_core_service_creator::class, $provider->applicationCoreServiceCreator());
        $this->assertInstanceOf(application_content_service_creator::class, $provider->applicationContentServiceCreator());
        $this->assertInstanceOf(application_navigation_service_creator::class, $provider->applicationNavigationServiceCreator());
        $this->assertInstanceOf(application_controller_service_creator::class, $provider->applicationControllerServiceCreator());
        $this->assertInstanceOf(application_infrastructure_service_creator::class, $provider->applicationInfrastructureServiceCreator());
        $this->assertInstanceOf(application_client_service_creator::class, $provider->applicationClientServiceCreator());
        $this->assertInstanceOf(application_pager_service_creator::class, $provider->applicationPagerServiceCreator());
        $this->assertInstanceOf(application_utility_service_creator::class, $provider->applicationUtilityServiceCreator());
        $this->assertFalse(method_exists($provider, 'applicationDatabaseServiceCreator'));
        $this->assertFalse(method_exists($provider, 'applicationEmailServiceCreator'));
        $this->assertInstanceOf(application_session_service_creator::class, $provider->applicationSessionServiceCreator());
        $this->assertInstanceOf(application_user_service_creator::class, $provider->applicationUserServiceCreator());
    }

